"""Primary-source Asia camp pass; dated windows do not invent course assignments."""
def add_more_asia(add, src, fit, profiles):
    def put(*args, **kwargs):
        add(*args, **kwargs)
        p=profiles[-1];p['checked']='2026-10-05'
        for s in p['sources']:s['checked']='2026-10-05'
        return p
    def price(year,label,included,extras,deposit,season=None):
        out=dict(year=year,label=label,included=included,extras=extras,deposit=deposit)
        if season:out['season']=season
        return out
    def variants(p,rows):
        p['timing']['session_details']=rows
        p['timing']['sessions']=[[r['start'],r['end']] for r in rows]
